ev('validationLossExtension.restoreContext();true');run('wait','--fn','Horizon.diagnostics.ready && document.getElementById("errorScreen").hidden');b=state();shot('webgl-context-restored.png');check('context restoration preserves observer',a['d']['camera']==b['d']['camera'] and a['d']['settings']==b['d']['settings'] and b['p']['glError']==0,b['p'])
